    "06-11": [
      {
        "title": "S. Barnabæ, apostoli",
        "page": 453,
        "kind": "proper",
        "data": {
          "entrance": "Beátus iste sanctus, qui annumerári méruit inter Apóstolos: erat enim vir bonus, et plenus Spíritu Sancto et fide (T.P. allelúia).",
          "collect": "Deus, qui beátum Bárnabam, plenum fide et Spíritu Sancto, ad géntium conversiónem segregáre præcepísti, concéde, ut Evangélium Christi, quod strénue prædicávit, ore et ópere fidéliter nuntiétur. Per Dóminum.",
          "prayer_offerings": "Obláta múnera, quǽsumus, Dómine, tua benedictióne sanctífica, quæ, te donánte, nos flamma tuæ dilectiónis accéndant, per quam beátus Bárnabas lumen Evangélii géntibus apportávit. Per Christum.",
          "communion": "Iam non dicam vos servos, quia servus nescit quid fáciat Dóminus eius. Vos autem dixi amícos, quia ómnia quæcúmque audívi a Patre meo, nota feci vobis (T.P. allelúia).",
          "prayer_after": "Ætérnæ pignus vitæ capiéntes, te, Dómine, humíliter implorámus, ut, quod pro beáti Bárnabæ apóstoli memória in imágine gérimus sacraménti, manifésta perceptióne sumámus. Per Christum."
        }
      }
    ],
    "06-13": [
      {
        "title": "S. Antonii de Padova, presbyteri et Ecclesiæ doctoris (p. 943), vel de Communi sanctorum: pro religiosis (p. 961).",
        "page": 454,
        "kind": "proper",
        "data": {
          "collect": "Omnípotens sempitérne Deus, qui pópulo tuo beátum Antónium prædicatórem insígnem dedísti, atque in necessitátibus intercessórem, concéde, ut, eius auxílio, christiánæ vitæ documénta sectántes, in ómnibus adversitátibus te subveniéntem sentiámus. Per Dóminum."
        }
      }
    ],
