    "08-20": [
      {
        "title": "S. Bernardi, abbatis et Ecclesiæ doctoris",
        "page": 483,
        "kind": "proper",
        "data": {
          "entrance": "Replévit beátum Bernárdum Dóminus spíritu intellegéntiæ, et ipse fluénta doctrínæ ministrávit pópulo Dei.",
          "collect": "Deus, qui beátum Bernárdum abbátem, zelo domus tuæ succénsum, in Ecclésia tua lucére simul et ardére fecísti, eius nobis intercessióne concéde, ut, eódem spíritu fervéntes, tamquam fílii lucis iúgiter ambulémus. Per Dóminum.",
          "prayer_offerings": "Maiestáti tuæ, Dómine, unitátis et pacis offérimus sacraméntum, sancti Bernárdi abbátis memóriam recoléntes, qui, verbo et ópere præclárus, Ecclésiæ tuæ órdinis concórdiam strénue procurávit. Per Christum.",
          "communion": "Sicut diléxit me Pater, et ego diléxi vos, dicit Dóminus; manéte in dilectióne mea.",
          "prayer_after": "Cibus, quem súmpsimus, Dómine, in celebratióne beáti Bernárdi, suum in nobis operétur efféctum, ut, eius exémplis roboráti et mónitis erudíti, Verbi tui incarnáti rapiámur amóre. Qui vivit et regnat in sǽcula sæculórum."
        }
      }
    ],
    "08-21": [
      {
        "title": "S. Pii X, papæ",
        "page": 483,
        "kind": "proper",
        "data": {
          "collect": "Deus, qui, ad tuéndam cathólicam fidem et univérsa in Christo instauránda, beátum Pium papam cælésti sapiéntia et apostólica fortitúdine replevísti, concéde propítius, ut, eius institúta et exémpla sectántes, prǽmia consequámur ætérna. Per Dóminum.",
          "prayer_offerings": "Oblatiónibus nostris, Dómine, benígne suscéptis, da, quǽsumus, ut hæc divína mystéria, beáti Pii papæ mónita secúti, sincéris tractémus obséquiis, et fidéli mente sumámus. Per Christum.",
          "prayer_after": "Memóriam beáti Pii papæ celebrántes, quǽsumus, Dómine Deus noster, ut, virtúte mensæ cæléstis, constántes efficiámur in fide, et in tua simus caritáte concórdes. Per Christum."
        }
      }
    ],
    "08-22": [
      {
        "title": "Beatæ Mariæ Virginis Reginæ",
        "page": 484,
        "kind": "proper",
        "data": {
          "entrance": "Astitit Regína a dextris tuis in vestítu deauráto, circúmdata varietáte.",
          "collect": "Deus, qui Fílii tui Genetrícem nostram constituísti Matrem atque Regínam, concéde propítius, ut, ipsíus intercessióne suffúlti, tuórum in regno cælésti consequámur glóriam filiórum. Per Dóminum.",
          "prayer_offerings": "Memóriam recoléntes beátæ Vírginis Maríæ, tibi, Dómine, múnera nostra offérimus, deprecántes, ut eius nobis succúrrat humánitas, qui tibi oblatiónem seípsum in cruce óbtulit immaculátam. Qui vivit et regnat in sǽcula sæculórum.",
          "communion": "Beáta es, quæ credidísti, quóniam perficiéntur ea, quæ dicta sunt tibi a Dómino.",
          "prayer_after": "Sumptis, Dómine, sacraméntis cæléstibus, te súpplices deprecámur, ut, qui beátæ Vírginis Maríæ memóriam venerándo recólimus, ætérni convívii mereámur esse partícipes. Per Christum."
        }
      }
    ],
