    "12-26": [
      {
        "title": "S. STEPHANI, PROTOMARTYRIS",
        "page": 532,
        "kind": "proper",
        "data": {
          "entrance": "Apértæ sunt iánuæ cæli beáto Stéphano, qui in número Mártyrum invéntus est primus, et ídeo triúmphat in cælis coronátus.",
          "collect": "Da nobis, quǽsumus, Dómine, imitári quod cólimus, ut discámus et inimícos dilígere, quia eius natalícia celebrámus, qui novit étiam pro persecutóribus exoráre. Per Dóminum.",
          "prayer_offerings": "Múnera, quǽsumus, Dómine, tibi sint hodiérnæ devotiónis accépta, quæ beáti Stéphani mártyris commemorátio gloriósa deprómit. Per Christum.",
          "communion": "Lapidábant Stéphanum, invocántem et dicéntem: Dómine Iesu, súscipe spíritum meum.",
          "prayer_after": "Grátias ágimus, Dómine, multiplicátis circa nos miseratiónibus tuis, qui et Fílii tui nativitáte nos salvas, et beáti mártyris Stéphani celebratióne lætíficas. Per Christum."
        }
      }
    ],
    "12-27": [
      {
        "title": "S. IOANNIS, APOSTOLI ET EVANGELISTÆ",
        "page": 533,
        "kind": "proper",
        "data": {
          "entrance": "Iste est Ioánnes, qui supra pectus Dómini in cena recúbuit: beátus Apóstolus, cui reveláta sunt secréta cæléstia, et verba vitæ in toto terrárum orbe diffúdit.\nVel:\nCf. Sir 15, 5\nIn médio Ecclésiæ apéruit os eius, et implévit eum Dóminus spíritu sapiéntiæ et intelléctus; stolam glóriæ índuit eum.",
          "collect": "Deus, qui per beátum apóstolum Ioánnem Verbi tui nobis arcána reserásti, præsta, quǽsumus, ut, quod ille nostris áuribus excellénter infúdit, intellegéntiæ competéntis eruditióne capiámus. Per Dóminum.",
          "prayer_offerings": "Múnera, quǽsumus, Dómine, obláta sanctífica, et præsta, ut ex huius cenæ convívio ætérni Verbi secréta hauriámus, quæ ex eódem fonte apóstolo tuo Ioánni revelásti. Per Christum.",
          "communion": "Verbum caro factum est, et habitávit in nobis. Et de plenitúdine eius nos omnes accépimus.",
          "prayer_after": "Præsta, quǽsumus, omnípotens Deus, ut Verbum caro factum, quod beátus Ioánnes apóstolus prædicávit, per hoc mystérium quod celebrávimus hábitet semper in nobis. Qui vivit et regnat in sǽcula sæculórum."
        }
      }
    ],
    "12-28": [
      {
        "title": "SS. INNOCENTIUM, MARTYRUM",
        "page": 534,
        "kind": "proper",
        "data": {
          "entrance": "Innocéntes pro Christo infántes occísi sunt, ipsum sequúntur Agnum sine mácula, et dicunt semper: Glória tibi, Dómine.",
          "collect": "Deus, cuius hodiérna die præcónium Innocéntes mártyres non loquéndo sed moriéndo conféssi sunt, da, quǽsumus, ut fidem tuam, quam lingua nostra lóquitur, étiam móribus vita fateátur. Per Dóminum.",
          "prayer_offerings": "Súscipe, Dómine, quǽsumus, devotórum múnera famulórum, et eos tuis purífica serviéntes pietáte mystériis, quibus étiam iustíficas ignorántes. Per Christum.",
          "communion": "Hi empti sunt ex homínibus, primítiæ Deo et Agno; hi sequúntur Agnum quocúmque íerit.",
          "prayer_after": "Salvatiónis abundántiam tríbue, Dómine, fidélibus in eórum festivitáte tua sancta suméntibus, qui, Fílium tuum humána necdum voce profiténtes, cælésti sunt grátia pro eius nativitáte coronáti. Qui vivit et regnat in sǽcula sæculórum."
        }
      }
    ],
